<script lang="ts">
 import {allowed} from '$lib/forms';
 import Icon from './Icon.svelte';import BarChart from './BarChart.svelte';import StatusChart from './StatusChart.svelte';
 let {section,model,t,lang,fullCosts=null,costTotals=null,user,tenant,onAction,onWork}:{section:string;model:Record<string,any[]>;t:(s:string)=>string;lang:string;fullCosts?:any;costTotals?:any;user:any;tenant:any;onAction:(type:string,defaults?:Record<string,string>)=>void;onWork:()=>void}=$props();
 const n=(v:any)=>Number(v??0),sum=(rows:any[],key:string)=>rows.reduce((total,row)=>total+n(row[key]),0),format=(v:any,digits=0)=>new Intl.NumberFormat(lang,{maximumFractionDigits:digits}).format(n(v));
 let vintage=$derived(Math.max(new Date().getFullYear(),...model.harvests.map(h=>n(h.vintage))));
 let alerts=$derived(model.lab_alerts.filter(a=>a.status!=='within_range'));let openTasks=$derived(model.tasks.filter(r=>r.status!=='done'));
 let metrics=$derived.by(()=>{
  const stock=n(model.statistics[0]?.physical_l),available=n(model.statistics[0]?.available_l);
  const money=(v:any)=>format(v,2)+' €';
  const sets:Record<string,{label:string;value:string;icon:string;tone?:string}[]>={
   today:[{label:'physical',value:format(stock,2)+' L',icon:'cellar'},{label:'available_l',value:format(available,2)+' L',icon:'bottling'},{label:'tasks',value:String(model.statistics[0]?.open_tasks??openTasks.length),icon:'today'},{label:'uxAttention',value:String(alerts.length),icon:'alert',tone:alerts.length?'warning':''}],
   vineyard:[{label:'vineyard',value:String(model.vineyards.length),icon:'vineyard'},{label:'area_ha',value:format(sum(model.vineyards,'area_ha'),2)+' ha',icon:'vineyard'},{label:'field_operations',value:String(model.field_operations.length),icon:'today'},{label:'maturity_samples',value:String(model.maturity_samples.length),icon:'harvest'}],
   harvest:[{label:'quantity_kg',value:format(sum(model.harvests.filter(h=>n(h.vintage)===vintage),'quantity_kg'))+' kg',icon:'harvest'},{label:'output_l',value:format(sum(model.harvest_yields.filter(y=>model.harvests.some(h=>h.id===y.harvest_id&&n(h.vintage)===vintage)),'output_l'))+' L',icon:'cellar'},{label:'harvest_plans',value:String(model.harvest_plans.filter(p=>!['completed','cancelled'].includes(p.status)).length),icon:'today'}],
   cellar:[{label:'physical',value:format(stock,2)+' L',icon:'cellar'},{label:'available_l',value:format(available,2)+' L',icon:'bottling'},{label:'uxCapacity',value:format(model.vessels.filter(v=>v.status==='ready').reduce((s,v)=>s+Math.max(0,n(v.capacity_l)-sum(model.positions.filter(p=>p.vessel_id===v.id),'quantity_l')),0))+' L',icon:'cellar'},{label:'blocked',value:String(model.vessels.filter(v=>v.status==='blocked').length),icon:'alert'}],
   blends:[{label:'project_id',value:String(model.projects.length),icon:'blends'},{label:'recipe_id',value:String(model.recipes.length),icon:'reports'},{label:'trial_id',value:String(model.trials.length),icon:'lab'},{label:'uxOpenOrders',value:String(model.orders.filter(o=>o.status==='approved').length),icon:'check'}],
   lab:[{label:'analyses',value:String(model.analyses.length),icon:'lab'},{label:'fermentations',value:String(model.fermentations.filter(f=>f.status==='active').length),icon:'cellar'},{label:'uxAttention',value:String(alerts.length),icon:'alert',tone:alerts.length?'warning':''},{label:'reference_samples',value:String(model.reference_samples.length),icon:'bottling'}],
   bottling:[{label:'bottling_plans',value:String(model.bottling_plans.filter(p=>p.status==='planned').length),icon:'today'},{label:'uxWineStock',value:format(sum(model.packaged_stock.filter(p=>p.stock_authority==='app'),'available')),icon:'bottling'},{label:'materials',value:String(model.materials.length),icon:'data'},{label:'uxAttention',value:String(model.materials.filter(m=>n(m.available)<n(m.reorder_at)).length),icon:'alert'}],
   hygiene:[{label:'uxMaintenance',value:String(model.maintenance.filter(m=>m.status!=='done').length),icon:'hygiene'},{label:'blocked',value:String([...model.resources,...model.vessels].filter(r=>r.status==='blocked').length),icon:'alert'},{label:'cleanings',value:String(model.cleanings.length),icon:'check'}],
   costing:[{label:'uxExtraCosts',value:money(costTotals?.actual??sum(model.costs.filter(c=>c.basis==='actual'),'amount')),icon:'costing'},{label:'uxPlanned',value:money(costTotals?.planned??sum(model.costs.filter(c=>c.basis==='planned'),'amount')),icon:'today'},{label:'cost_allocations',value:String(model.cost_allocations.length),icon:'blends'}],
   reports:[{label:'reports',value:String(model.reports.length),icon:'reports'},{label:'rule_sets',value:String(model.rule_sets.length),icon:'hygiene'},{label:'validation_findings',value:String(model.validation_findings.length),icon:'check'}],
   data:[{label:'connections',value:String(model.connections.length),icon:'data'},{label:'active',value:String(model.connections.filter(c=>c.enabled).length),icon:'check'},{label:'outbox',value:String(model.outbox.filter(o=>o.status==='pending').length),icon:'today'}],
   admin:[{label:'winery',value:tenant.name,icon:'vineyard'},{label:'members',value:String(model.members.length),icon:'admin'},{label:'security',value:t(user.twoFactorEnabled?'active':'disabled'),icon:'hygiene',tone:user.twoFactorEnabled?'good':'warning'}]
  };return sets[section]??[];
 });
 function grouped(rows:any[],label:(r:any)=>string,value:(r:any)=>number){const map=new Map<string,number>();for(const r of rows){const key=label(r)||t('uxUnknown');map.set(key,(map.get(key)??0)+value(r));}return [...map].map(([label,value])=>({label,value})).sort((a,b)=>b.value-a.value).slice(0,8);}
 let stocks=$derived(grouped(model.positions.filter(p=>n(p.quantity_l)>0),p=>model.lots.find(l=>l.id===p.lot_id)?.grape||t('uxBlendOrUnknown'),p=>n(p.quantity_l)));
 let areas=$derived(grouped(model.vineyards,v=>v.grape,v=>n(v.area_ha)));
 let taskStates=$derived(['open','doing','done'].map((label,i)=>({label,value:model.tasks.filter(t=>t.status===label).length,tone:['warning','info','good'][i]})));
 let labStates=$derived(['within_range','outside_range','stale','missing','incompatible'].map((status,i)=>({label:status==='within_range'?'uxGood':status==='missing'?'uxMissing':status,value:model.lab_alerts.filter(a=>a.status===status).length,tone:['good','bad','warning','warning','info'][i]})));
 let harvestData=$derived(model.vineyards.map(v=>({label:v.code,value:sum(model.harvests.filter(h=>h.vineyard_id===v.id&&n(h.vintage)===vintage),'quantity_kg'),comparison:sum(model.harvest_plans.filter(p=>p.vineyard_id===v.id&&n(p.vintage)===vintage&&p.status!=='cancelled'),'planned_kg')})));
</script>
{#if metrics.length}<div class="metrics">{#each metrics as metric}<article class="metric"><div class="metric-label"><span>{t(metric.label)}</span><span class={'metric-icon '+(metric.tone??'')}><Icon name={metric.icon} size={18}/></span></div><strong class:long={metric.value.length>22}>{metric.value}</strong></article>{/each}</div>{/if}
{#if Object.values(model).some(rows=>rows.length>=500)}<p class="notice">{t('uxSample')}</p>{/if}
{#if section==='today'}<div class="insights"><BarChart title={t('uxStockGrape')} data={stocks} unit="L" {t} {lang} valueLabel="physical"/><StatusChart title={t('uxTaskStatus')} items={taskStates} {t}/></div>{/if}
{#if section==='vineyard'}<div class="insights"><BarChart title={t('uxAreaGrape')} data={areas} unit="ha" {t} {lang} valueLabel="area_ha"/><section class="card"><h2>{t('vineyard')}</h2><div class="parcel-cards">{#each model.vineyards as v}<a href={'/app/vineyard?vineyard='+v.id}><span class="parcel-mark"><Icon name="vineyard" size={22}/></span><span><strong>{v.name}</strong><small>{v.code} · {v.grape} · {format(v.area_ha,2)} ha</small></span><Icon name="arrow" size={17}/></a>{:else}<p class="empty-state">{t('uxEmptyHint')}</p>{/each}</div></section></div>{/if}
{#if section==='harvest'}<BarChart title={t('uxHarvestCompare')+' · '+vintage} data={harvestData} unit="kg" comparisonLabel="uxPlanned" {t} {lang}/>{/if}
{#if section==='blends'}<section class="card"><h2>{t('uxBlendFlow')}</h2><div class="workflow">{#each ['project_create','recipe_save','recipe_freeze','trial','evaluate','approve','produce'] as type,i}<button class="flow-step" disabled={!allowed(type,tenant.role)} onclick={()=>onAction(type)}><span class="step-number">{i+1}</span><span>{t(type)}</span><Icon name="arrow" size={16}/></button>{/each}</div></section>{/if}
{#if section==='lab'}<StatusChart title={t('uxLabStatus')} items={labStates} {t}/>{/if}
{#if section==='bottling'}<BarChart title={t('uxBottlingCompare')} data={model.packaged_stock.filter(p=>p.stock_authority==='app').map(p=>({label:p.code,value:n(p.available),comparison:n(p.bottle_count)})).slice(0,8)} unit={t('uxBottles')} valueLabel="available" comparisonLabel="bottle_count" {t} {lang}/><div class="record-cards">{#each model.bottling_plans.filter(p=>p.status==='planned') as plan}<article class="card"><span class="pill info">{t(plan.status)}</span><h3>{plan.name}</h3><p>{format(plan.bottle_count)} · {t('bottle_count')}</p><p class="muted">{new Intl.DateTimeFormat(lang,{dateStyle:'medium',timeZone:tenant.timezone}).format(new Date(plan.starts_at))} · {plan.supplier}</p><button class="secondary" disabled={!allowed('bottling_execute',tenant.role)} onclick={()=>onAction('bottling_execute',{plan_id:plan.id,code:'',bottle_count:String(plan.bottle_count),loss_l:String(plan.loss_l)})}>{t('bottling_execute')} <Icon name="arrow" size={16}/></button></article>{/each}</div>{/if}
{#if section==='hygiene'}<StatusChart title={t('resources')} items={['ready','blocked','cleaning'].map((status,i)=>({label:status,value:[...model.vessels,...model.resources].filter(r=>r.status===status).length,tone:['good','bad','warning'][i]}))} {t}/><div class="record-cards">{#each model.maintenance.filter(m=>m.status!=='done') as record}<article class="card"><span class="pill warning">{t(record.status)}</span><h3>{record.title}</h3><p class="muted">{record.findings}</p><button class="secondary" disabled={!allowed('maintenance_update',tenant.role)} onclick={()=>onAction('maintenance_update',{maintenance_id:record.id})}>{t('maintenance_update')}</button></article>{:else}<section class="card"><p class="muted">{t('noAlerts')}</p></section>{/each}</div>{/if}
{#if section==='costing'&&fullCosts}<BarChart title={t('uxCostsCompare')} data={fullCosts.lots.slice(0,8).map((l:any)=>({label:l.code,value:n(l.total_actual),comparison:n(l.total_planned)}))} unit="EUR" comparisonLabel="uxPlanned" {t} {lang}/>{/if}
{#if section==='data'}<div class="record-cards">{#each model.connections as c}<article class="card"><div class="actions"><Icon name="data"/><span class={'pill '+(c.enabled?'good':'info')}>{t(c.enabled?'active':'disabled')}</span></div><h3>{c.name}</h3><p class="muted">{c.adapter==='openai-compatible'?'OpenAI':c.adapter==='file'?'CSV · JSON · XLSX · GeoJSON':c.adapter==='winestro'?'Winestro':c.adapter}</p>{#if c.adapter==='file'}<a href="/app/data/import">{t('import')} →</a>{:else}<button class="secondary" onclick={onWork}>{t('connections')} →</button>{/if}</article>{/each}</div><section class="card"><h2>{t('download')}</h2><div class="actions">{#each ['json','csv','xlsx'] as format}<a href={'/api/export?format='+format}>{format.toUpperCase()}</a>{/each}<a href="/api/gis">GeoJSON</a></div></section>{/if}
{#if section==='harvest'}<div class="record-cards">{#each model.harvest_plans.filter(p=>!['completed','cancelled'].includes(p.status)).slice(0,4) as plan}<article class="card"><span class="pill info">{t(plan.status)}</span><h3>{plan.vineyard_code} · {format(plan.planned_kg)} kg</h3><p class="muted">{new Intl.DateTimeFormat(lang,{dateStyle:'medium',timeStyle:'short',timeZone:tenant.timezone}).format(new Date(plan.starts_at))} · {plan.resource_name??plan.supplier}</p><button class="secondary" disabled={!allowed('harvest_plan_update',tenant.role)} onclick={()=>onAction('harvest_plan_update',{plan_id:plan.id})}>{t('harvest_plan_update')}</button></article>{/each}</div>{/if}
{#if section==='assistant'}<div class="capabilities">{#each [{label:'uxLocalOcr',icon:'reports',status:'uxReady'},{label:'uxSpeech',icon:'assistant',status:'uxSpeechHint'},{label:'uxAi',icon:'blends',status:model.connections.some(c=>c.adapter==='openai-compatible'&&c.enabled)?'active':'uxProviderNeeded'}] as c}<article class="card"><Icon name={c.icon} size={25}/><h3>{t(c.label)}</h3><p class="muted">{t(c.status)}</p></article>{/each}</div>{/if}
{#if section==='reports'&&['owner','oenologist','office'].includes(tenant.role)&&model.reports.length}<section class="card"><h2>{t('uxReportLibrary')}</h2><div class="report-cards">{#each model.reports.slice(0,8) as report}<article><span class="file-mark"><Icon name="reports" size={22}/></span><div><strong>{t(report.kind)}</strong><small>{new Intl.DateTimeFormat(lang,{dateStyle:'medium',timeZone:tenant.timezone}).format(new Date(report.created_at))}</small></div><a href={'/api/reports?id='+report.id} aria-label={t(report.kind)+' PDF'}>PDF</a><a href={'/api/reports?id='+report.id+'&format=csv'} aria-label={t(report.kind)+' CSV'}>CSV</a></article>{/each}</div></section>{/if}
<style>.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(185px,1fr));gap:16px;margin-bottom:24px}.metric{border:1px solid var(--line);background:white;padding:20px 21px;border-radius:13px;box-shadow:var(--shadow)}.metric-label{display:flex;align-items:center;justify-content:space-between;gap:8px;color:var(--muted);font-size:12px}.metric-icon{display:grid;place-items:center;width:32px;height:32px;border-radius:9px;color:var(--brand);background:var(--tint);flex-shrink:0}.metric-icon.warning{background:#fff4dc;color:#9c680f}.metric strong{display:block;font-size:27px;font-weight:700;letter-spacing:-.6px;margin-top:12px;line-height:1.25;font-variant-numeric:tabular-nums}.metric strong.long{font-size:19px}.insights{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(0,1fr);gap:20px}.record-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:18px}.record-cards .card{margin-bottom:20px}.record-cards button{display:flex;align-items:center;gap:10px}.parcel-cards{display:grid;gap:10px;max-height:315px;overflow:auto}.parcel-cards a{display:flex;align-items:center;gap:12px;border:1px solid var(--line);padding:12px;border-radius:9px;text-decoration:none;color:var(--ink)}.parcel-cards a:hover{background:var(--tint)}.parcel-cards a>span:nth-child(2){flex:1}.parcel-cards strong{font-size:12px;display:block}.parcel-cards small{display:block;font-size:11px;color:var(--muted);margin-top:3px}.parcel-mark,.file-mark{display:grid;place-items:center;width:40px;height:40px;border-radius:9px;background:var(--tint);color:var(--brand);flex-shrink:0}.workflow{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:8px}.flow-step{display:flex;align-items:center;gap:9px;color:var(--ink);background:#f5f9f6;border:1px solid var(--line);font-size:11px;text-align:left;padding:12px 9px}.flow-step>span:nth-child(2){flex:1}.flow-step:hover{background:var(--tint)}.step-number{display:grid;place-items:center;width:23px;height:23px;border-radius:50%;background:white;border:1px solid var(--line);color:var(--brand);flex-shrink:0;font-size:10px}.capabilities{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.capabilities :global(svg){color:var(--brand)}.report-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(290px,1fr));gap:12px}.report-cards article{display:flex;align-items:center;gap:10px;padding:12px;border:1px solid var(--line);border-radius:9px}.report-cards article>div{flex:1}.report-cards strong{font-size:12px;display:block}.report-cards small{display:block;font-size:11px;color:var(--muted)}.report-cards a{font-size:11px;font-weight:600;padding:8px 3px}@media(max-width:1050px){.insights{grid-template-columns:1fr 1fr}.metrics{grid-template-columns:repeat(2,1fr)}.workflow{grid-template-columns:repeat(3,1fr)}}@media(max-width:640px){.metrics{gap:10px}.metric{padding:15px}.metric strong{font-size:22px}.metric-label{font-size:11px}.insights,.capabilities{grid-template-columns:1fr}.workflow{grid-template-columns:repeat(2,1fr)}.record-cards{grid-template-columns:1fr}}</style>
